const publicMooringsLayer = L.markerClusterGroup({ maxClusterRadius: 40 });

publicMoorings.forEach(function (m) {
  const icon = L.divIcon({
    className: "custom-marker",
    html: `<div style="background:${m.color}; width:12px; height:12px; border-radius:50%; border:2px solid white;"></div>`,
    iconSize: [16, 16]
  });
  L.marker([m.lat, m.lng], { icon: icon })
    .bindPopup(`<strong>${m.type}</strong><br>${m.description}<br>${m.purpose}`)
    .addTo(publicMooringsLayer);
});
